    $club='own-reminder-native';$admin='own-reminder-native-admin';$actor='own-reminder-native-finance';$privateSeed=random_bytes(32);$privateKey=hash_hkdf('sha256',$privateSeed,32,'kulturhus-manager-master-v1');$key=static fn():string=>bin2hex(random_bytes(16));
