        $data=['invoice_format'=>'pdf','domestic_confirmed'=>'1','seller_contact'=>'Own original invoice office','buyer_name'=>$marker,'buyer_street'=>'Own original road 7','buyer_postcode'=>'23456','buyer_city'=>'Own original town','buyer_email'=>'buyer@example.invalid','buyer_reference'=>'OWN-118','description'=>'Own genuine service '.$marker,'note'=>"Own original note\n0 🙂",'vat_reason'=>'','document_date'=>'2025-12-01','delivery_date'=>'2025-12-01','due_date'=>'2025-12-15','category'=>'rooms','contact_id'=>'','payment_account'=>$account,'positions'=>[['description'=>'Own original service','quantity'=>'3','unit'=>'DAY','unit_gross'=>'119','tax_rate'=>'19','sphere'=>'2','account'=>'']]];
        $invoice=$invoices->save('',0,$data,$key());$invoices->review($invoice,1);$entry=$invoices->issue($invoice,2);if($partial)$finance->recordPayment($entry,1,$account,'2025-12-02','119');$row=$invoices->get($invoice);$original=ReminderSource::read($db,$admin,$invoice,$day);return ['invoice'=>$invoice,'document'=>$row['document_id'],'number'=>$row['number'],'entry'=>$entry,'amount_cents'=>$original['open_cents'],'recipient'=>$marker,'file'=>$docs->file($row['document_id'],1)];
    };
    $native=new ReminderRequests($db,$actor,$privateKey);$single=$source('Own genuine native reminder recipient',true);$input=$native->initial($single['invoice'],$day);$input['reason']="\n0\r\nOwn native complete reason 👩🏽‍💻";
    $denyCode=static function(callable $fn,int $code,string $label)use($check):void{try{$fn();}catch(DomainException $failure){$check($failure->getCode()===$code,$label);return;}throw new RuntimeException('Expected own reminder denial '.$label);};
